(() => {
  // 自动定位主酒馆窗口（兼容 iframe 沙箱）
  let W = window;
  try { while (!W.document.getElementById('chat') && W !== W.parent) W = W.parent; } catch (e) {}
  const D = W.document, chat = D.getElementById('chat');
  if (!chat) return console.warn('[批注] 找不到 #chat');

  W.__anno?.();
  D.getElementById('anno-style')?.remove();
  const css = D.createElement('style');
  css.id = 'anno-style';
  css.textContent = `
    .anno{cursor:pointer;border-bottom:1.5px dashed var(--SmartThemeQuoteColor,#c9962f);}
    .anno-pop{position:fixed;z-index:99999;max-width:206px;padding:5px 10px;border-radius:12px;cursor:pointer;
      font-family:"LXGW WenKai","LXGW WenKai Screen","Kaiti SC","STKaiti","KaiTi","楷体",serif;font-size:11.5px;line-height:1.5;letter-spacing:.01em;
      --anno-base:#f4f4f6;--anno-accent:var(--SmartThemeQuoteColor,#c9962f);
      background-color:var(--anno-base);
      background-image:linear-gradient(var(--SmartThemeBlurTintColor,transparent),var(--SmartThemeBlurTintColor,transparent)),linear-gradient(var(--SmartThemeBlurTintColor,transparent),var(--SmartThemeBlurTintColor,transparent));
      -webkit-backdrop-filter:blur(14px) saturate(150%);backdrop-filter:blur(14px) saturate(150%);
      border:1px solid var(--SmartThemeBorderColor,rgba(127,127,127,.22));
      color:var(--SmartThemeBodyColor,#1c1c1e);
      opacity:0;transform-origin:top left;}
    .anno-pop.show{animation:annoPop .26s cubic-bezier(.34,1.56,.64,1) both,annoBreath 3s ease-in-out infinite;}
    .anno-pop.hide{animation:annoOut .18s ease forwards;}
    @keyframes annoPop{0%{opacity:0;transform:translateY(6px) scale(.9);}60%{opacity:1;transform:translateY(0) scale(1.03);}100%{opacity:1;transform:none;}}
    @keyframes annoOut{to{opacity:0;transform:translateY(2px) scale(.92);}}
    @keyframes annoBreath{0%,100%{border-color:color-mix(in srgb,var(--anno-accent) 22%,transparent);box-shadow:0 0 0 0 transparent;}50%{border-color:color-mix(in srgb,var(--anno-accent) 65%,transparent);box-shadow:0 0 5px 0 color-mix(in srgb,var(--anno-accent) 18%,transparent);}}
    @media (prefers-color-scheme:dark){.anno-pop{--anno-base:#202024;color:var(--SmartThemeBodyColor,#eee);}}
    .anno-pop .row{margin:2px 0;}
    .anno-pop b{color:var(--SmartThemeQuoteColor,#b8860b);font-weight:600;}
    .anno-mono-name{font-weight:600;font-size:10.5px;color:var(--SmartThemeQuoteColor,#b8860b);margin-bottom:3px;letter-spacing:.04em;}
    .anno-mono{font-style:italic;opacity:.92;}`;
  D.head.appendChild(css);
  // 加载网络楷体（霞鹜文楷），保证无内置楷体的设备也能显示
  if (!D.getElementById('anno-font')) { const lk = D.createElement('link'); lk.id = 'anno-font'; lk.rel = 'stylesheet'; lk.href = 'https://fastly.jsdelivr.net/npm/lxgw-wenkai-webfont/style.css'; D.head.appendChild(lk); }

  const RE = /\[\[(金句|高燃|转折)\]\]([\s\S]*?)\[\[网友\]\]([\s\S]*?)\[\[心声\]\]([\s\S]*?)\[\[\/\]\]/g;
  const ea = s => s.replace(/"/g, '&quot;');
  // 去掉酒馆渲染出的 <q> 等标签，只留纯文本
  const strip = (h) => { const d = D.createElement('div'); d.innerHTML = h; return (d.textContent || '').trim(); };
  const scan = () => D.querySelectorAll('#chat .mes_text').forEach(el => {
    if (!el.innerHTML.includes('[[')) return;
    el.innerHTML = el.innerHTML.replace(RE, (_, t, txt, c, m) =>
      `<span class="anno anno-${t}" data-c="${ea(strip(c))}" data-m="${ea(strip(m))}">${txt}</span>`);
  });
  scan();
  const obs = new MutationObserver(() => scan());
  obs.observe(chat, { childList: true, subtree: true });

  const esc = s => s.replace(/[&<>]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;' }[c]));
  const charOf = (span) => span.closest('.mes')?.getAttribute('ch_name') || span.closest('.mes')?.querySelector('.name_text')?.textContent?.trim() || '内心独白';
  const html = (span, view) => view === 'c'
    ? (span.dataset.c || '').split('｜').map(s =>
        `<div class="row"><b>${esc(s.split(/：|:/)[0])}</b>：${esc(s.split(/：|:/).slice(1).join(''))}</div>`).join('')
    : `<div class="anno-mono-name">${esc(charOf(span))}</div><div class="anno-mono">${esc(span.dataset.m || '')}</div>`;
  let pop = null, cur = null;
  // 跟随：根据点击点相对文字的偏移定位
  const place = () => {
    if (!cur || !pop) return;
    const r = cur.span.getBoundingClientRect();
    const x = r.left + cur.ox, y = r.top + cur.oy;
    pop.style.left = Math.max(8, Math.min(x, W.innerWidth - pop.offsetWidth - 8)) + 'px';
    pop.style.top = (y + 14) + 'px';
  };
  const closePop = () => {
    if (!pop) return;
    const p = pop; pop = null; cur = null;
    p.classList.remove('show'); p.classList.add('hide');
    p.addEventListener('animationend', () => p.remove(), { once: true });
    setTimeout(() => { if (p.parentNode) p.remove(); }, 300);
  };
  const open = (span, view, ox, oy) => {
    pop?.remove();
    pop = D.createElement('div'); pop.className = 'anno-pop';
    pop.innerHTML = html(span, view);
    D.body.appendChild(pop);
    cur = { span, view, ox, oy };
    place();
    requestAnimationFrame(() => pop.classList.add('show'));
  };
  const swap = (view) => {
    if (!pop || !cur) return;
    cur.view = view;
    pop.innerHTML = html(cur.span, view);
    place();
  };
  let raf = 0;
  const reflow = () => { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; place(); }); };
  D.addEventListener('scroll', reflow, true);
  W.addEventListener('resize', reflow);
  const onClick = (e) => {
    const span = e.target.closest('.anno');
    if (span) {
      e.stopPropagation();
      if (cur?.span !== span) { const r = span.getBoundingClientRect(); open(span, 'c', e.clientX - r.left, e.clientY - r.top); }
      else swap(cur.view === 'c' ? 'm' : 'c');
    } else if (cur && e.target.closest('.anno-pop')) {
      e.stopPropagation();
      swap(cur.view === 'c' ? 'm' : 'c');
    } else {
      closePop();
    }
  };
  D.addEventListener('click', onClick, true);

  W.__anno = () => { obs.disconnect(); D.removeEventListener('click', onClick, true); D.removeEventListener('scroll', reflow, true); W.removeEventListener('resize', reflow); pop?.remove(); pop = null; cur = null; css.remove(); D.getElementById('anno-font')?.remove(); };
})();
